input.command:
cd /home/user/rork-app && echo "=== 10. PUBLIC ENDPOINTS ===" && for url in "https://api.ivxholding.com/health" "https://api.ivxholding.com/version" "https://api.ivxholding.com/readiness" "https://ivxholding.com" "https://chat.ivxholding.com"; do
  CODE=$(curl -sS -o /dev/null -w "%{http_code}" -m 10 "$url" 2>/dev/null)
  echo "  $url → HTTP $CODE"
done && echo "" && echo "=== 11. PRODUCTION CHAT TEST (public endpoint) ===" && curl -sS -X POST https://api.ivxholding.com/public/chat -H "Content-Type: application/json" -d '{"message":"hello","roomId":"main-room"}' -m 15 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
console.log('  reply:', d.reply?.slice(0,80) || 'none');
console.log('  model:', d.model || 'none');
console.log('  provider:', d.provider || 'none');
console.log('  ok:', d.ok);
" 2>&1 && echo "" && echo "=== 12. CI JOB DETAILS (expanded test suite) ===" && curl -sS -H "Accept: application/vnd.github+json" "https://api.github.com/repos/ibb142/ivx-holdings-platform/actions/runs?per_page=1" 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const r=d.workflow_runs?.[0];
console.log('  Run ID:', r.id);
console.log('  SHA:', r.head_sha?.slice(0,8));
console.log('  Status:', r.status + '/' + r.conclusion);
console.log('  Jobs:');
" 2>&1 && curl -sS -H "Accept: application/vnd.github+json" "https://api.github.com/repos/ibb142/ivx-holdings-platform/actions/runs/30177724685/jobs" 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
if (d.jobs) {
  d.jobs.forEach(j => console.log('    ' + j.name + ' → ' + j.status + '/' + j.conclusion));
}" 2>&1

